    cursor = find_cursor(board)

    # Check for massive reset
    if action == 'RIGHT' and cursor and cursor == (29, 53):
        return get_reset_board((49, 52))
    if action == 'LEFT' and cursor and cursor == (40, 31):
        return get_reset_board((40, 31))

    if action in ('UP', 'DOWN', 'LEFT', 'RIGHT'):
        # Determine move count from orange blocks
        move_count = get_move_count_from_orange(board)

        # Clear cursor
        if cursor:
            r, c = cursor
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if 0 <= r+dr < 64 and 0 <= c+dc < 64:
                        board[r+dr][c+dc] = 'w'

        # Move cursor
        if cursor:
            r, c = cursor
            if action == 'UP':
                r -= 3
            elif action == 'DOWN':
                r += 3
            elif action == 'LEFT':
                c -= 3
            elif action == 'RIGHT':
                c += 3
            r = max(1, min(62, r))
            c = max(1, min(62, c))
            cursor = (r, c)

        # Draw cursor
        if cursor:
            r, c = cursor
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if 0 <= r+dr < 64 and 0 <= c+dc < 64:
                        if dr == 0 and dc == 0:
                            board[r+dr][c+dc] = 'W'
                        else:
                            board[r+dr][c+dc] = 'N'

        # Activate red blocks based on move count
        if move_count == 0:
            activate_red(board, 15)
            activate_red(board, 50)
        elif move_count == 1:
            activate_red(board, 16)
            activate_red(board, 49)
        elif move_count == 2:
            activate_red(board, 17)
            activate_red(board, 48)
        elif move_count == 3:
            activate_red(board, 18)
            activate_red(board, 47)
        elif move_count == 4:
            activate_red(board, 19)
            activate_red(board, 46)
        elif move_count == 5:
            reset_orange(board)

        # Remove one c from bottom row
        for col in range(63, -1, -1):
            if board[63][col] == 'c':
                board[63][col] = 'W'
                break

