    if action == "MOUSE":
        return board_lines

    # Move Y cursor down
    for r in range(n):
        if board[r][63] == 'Y':
            board[r][63] = 'B'
            if r + 1 < n:
                board[r + 1][63] = 'Y'
            break

    if action == "SPACE":
        return [''.join(row) for row in board]

    # Set directions
    if action == "LEFT":
        bd = (0, -1); cd = (0, 1); dist = 9
    elif action == "RIGHT":
        bd = (0, 1); cd = (0, -1); dist = 9
    elif action == "UP":
        bd = (-1, 0); cd = (-1, 0); dist = 3
    elif action == "DOWN":
        bd = (1, 0); cd = (1, 0); dist = 3
    else:
        return [''.join(row) for row in board]

    # Find all connected components (blocks)
    visited = [[False]*n for _ in range(n)]
    blocks = []  # (type, cells, colors)

    for r in range(n):
        for c in range(n):
            if visited[r][c]:
                continue
            ch = board[r][c]
            if ch not in ('B', 'W', 'c'):
                continue

            if ch == 'c':
                typ = 'c'
                allowed = {'c'}
            else:
                typ = 'B'
                allowed = {'B', 'W'}

            stack = [(r, c)]
            visited[r][c] = True
            cells = []
            colors = []

            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                colors.append(board[cr][cc])

                for nr, nc in [(cr+1,cc), (cr-1,cc), (cr,cc+1), (cr,cc-1)]:
                    if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc]:
                        if board[nr][nc] in allowed:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

            blocks.append((typ, cells, colors))

    # Move each block
    for typ, cells, colors in blocks:
        if typ == 'B':
            d = bd
        else:
            d = cd

        # Calculate maximum possible move distance
        max_d = dist
        for (r, c) in cells:
            for step in range(1, dist + 1):
                nr, nc = r + d[0]*step, c + d[1]*step
                if not (0 <= nr < n and 0 <= nc < n):
                    max_d = min(max_d, step - 1)
                    break
                if board[nr][nc] != 'b':
                    if (nr, nc) not in cells:
                        max_d = min(max_d, step - 1)
                        break

        if max_d > 0:
            # Clear old positions
            for r, c in cells:
                board[r][c] = 'b'
            # Place at new positions
            for (r, c), col in zip(cells, colors):
                nr, nc = r + d[0]*max_d, c + d[1]*max_d
                board[nr][nc] = col

    return [''.join(row) for row in board]

