            for c in range(10, 56):
                if board[r][c] != 'B':
                    object_cells.append((r, c, board[r][c]))

        for r, c, _ in object_cells:
            board[r][c] = 'B'

        dr, dc = 0, 0
        if action == "UP":
            dr = -1
        elif action == "DOWN":
            dr = 1
        elif action == "LEFT":
            dc = -1
        elif action == "RIGHT":
            dc = 1

        for r, c, color in object_cells:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 64 and 0 <= nc < 64:
                board[nr][nc] = color

        # Bottom row: remove rightmost charcoal
        rightmost_c = -1
        for c in range(64):
            if board[63][c] == 'c':
                rightmost_c = c

        if rightmost_c >= 0:
            board[63][rightmost_c] = 'B'

        return [''.join(row) for row in board]

    elif action.startswith("MOUSE"):
        import re
        match = re.search(r'MOUSE\(row=(\d+), col=(\d+)\)', action)
        if not match:
            return board_lines

        row, col = int(match.group(1)), int(match.group(2))

        # Toggle switches at row 7
        if col >= 40:
            for c in range(38, 43):
                if board[7][c] == 'W':
                    board[7][c] = 'G'
                elif board[7][c] == 'G':
                    board[7][c] = 'W'
            for c in range(44, 49):
                if board[7][c] == 'W':
                    board[7][c] = 'G'
                elif board[7][c] == 'G':
                    board[7][c] = 'W'
        else:
            for c in range(32, 37):
                if board[7][c] == 'W':
                    board[7][c] = 'G'
                elif board[7][c] == 'G':
                    board[7][c] = 'W'
            for c in range(44, 49):
                if board[7][c] == 'W':
                    board[7][c] = 'G'
                elif board[7][c] == 'G':
                    board[7][c] = 'W'

        # Change colors in the paint area (rows 40-56)
        for r in range(40, 57):
            for c in range(10, 51):
                if board[r][c] == 'p':
                    board[r][c] = 'O'
                elif board[r][c] == 'O':
                    board[r][c] = 'W'
                elif board[r][c] == 'W':
                    board[r][c] = 'p'

        # Bottom row: remove rightmost charcoal
        rightmost_c = -1
        for c in range(64):
            if board[63][c] == 'c':
                rightmost_c = c

        if rightmost_c >= 0:
            board[63][rightmost_c] = 'B'

        return [''.join(row) for row in board]

    return board_lines
